package org.openqa.selenium.internal;

import java.util.Collections;
import java.util.Iterator;
import java.util.function.Function;
import java.util.stream.Stream;

public class Either<A, B> implements Iterable<B> {
  private final A left;
  private final B right;

  private Either(A a, B b) {
    left = a;
    right = b;
  }

  public static <A, B> Either<A, B> left(A a) {
    return new Either<>(a, null);
  }

  public static <A, B> Either<A, B> right(B b) {
    return new Either<>(null, b);
  }

  public boolean isLeft() {
    return left != null;
  }

  public boolean isRight() {
    return right != null;
  }

  public A left() {
    return left;
  }

  public B right() {
    return right;
  }

  public <R> R map(Function<? super B, ? extends R> mapper) {
    Require.nonNull("Mapper", mapper);
    return mapper.apply(right());
  }

  public <R> R mapLeft(Function<? super A, ? extends R> mapper) {
    Require.nonNull("Mapper", mapper);
    return mapper.apply(left());
  }

  @Override
  public Iterator<B> iterator() {
    return Collections.singleton(right()).iterator();
  }

  public Stream<B> stream() {
    return Stream.of(right());
  }

  @Override
  public String toString() {
    return "[Either(" + (isLeft() ? "left" : "right") + "): " + (isLeft() ? left() : right()) + "]";
  }

  /**
   * Standalone test driver that demonstrates the map/mapLeft bug.
   * Run: java org.openqa.selenium.internal.Either
   * Exit code 0 = all pass, 1 = failures
   */
  public static void main(String[] args) {
    int failures = 0;

    // Test 1: map() on left Either should NOT call mapper
    try {
      Either<String, Integer> either = Either.left("leftValue");
      if (!either.isLeft() || either.isRight()) {
        throw new AssertionError("Either should be left");
      }
      java.util.concurrent.atomic.AtomicBoolean called =
          new java.util.concurrent.atomic.AtomicBoolean(false);
      Function<Integer, String> mapper = (v) -> {
        called.set(true);
        throw new AssertionError("mapper should not have been called for left Either");
      };
      String result = either.map(mapper);
      if (result != null) {
        throw new AssertionError("result should be null, got: " + result);
      }
      if (called.get()) {
        throw new AssertionError("mapper should NOT have been invoked for left Either");
      }
      System.out.println("PASS: map on left Either should not call mapper");
    } catch (AssertionError e) {
      System.out.println("FAIL: map on left Either should not call mapper - " + e.getMessage());
      failures++;
    }

    // Test 2: map() on right Either SHOULD call mapper
    try {
      Either<String, Integer> either = Either.right(42);
      if (either.isLeft() || !either.isRight()) {
        throw new AssertionError("Either should be right");
      }
      Function<Integer, String> mapper = (v) -> v.toString();
      String result = either.map(mapper);
      if (!"42".equals(result)) {
        throw new AssertionError("expected 42, got: " + result);
      }
      System.out.println("PASS: map on right Either should call mapper");
    } catch (AssertionError e) {
      System.out.println("FAIL: map on right Either should call mapper - " + e.getMessage());
      failures++;
    }

    // Test 3: mapLeft() on right Either should NOT call mapper
    try {
      Either<String, Integer> either = Either.right(42);
      if (either.isLeft() || !either.isRight()) {
        throw new AssertionError("Either should be right");
      }
      java.util.concurrent.atomic.AtomicBoolean called =
          new java.util.concurrent.atomic.AtomicBoolean(false);
      Function<String, Integer> mapper = (v) -> {
        called.set(true);
        throw new AssertionError("mapper should not have been called for right Either");
      };
      Integer result = either.mapLeft(mapper);
      if (result != null) {
        throw new AssertionError("result should be null, got: " + result);
      }
      if (called.get()) {
        throw new AssertionError("mapper should NOT have been invoked for right Either");
      }
      System.out.println("PASS: mapLeft on right Either should not call mapper");
    } catch (AssertionError e) {
      System.out.println("FAIL: mapLeft on right Either should not call mapper - " + e.getMessage());
      failures++;
    }

    // Test 4: mapLeft() on left Either SHOULD call mapper
    try {
      Either<String, Integer> either = Either.left("leftValue");
      if (!either.isLeft() || either.isRight()) {
        throw new AssertionError("Either should be left");
      }
      Function<String, Integer> mapper = (v) -> v.length();
      Integer result = either.mapLeft(mapper);
      if (!result.equals(9)) {
        throw new AssertionError("expected 9, got: " + result);
      }
      System.out.println("PASS: mapLeft on left Either should call mapper");
    } catch (AssertionError e) {
      System.out.println("FAIL: mapLeft on left Either should call mapper - " + e.getMessage());
      failures++;
    }

    System.out.println();
    if (failures > 0) {
      System.out.println(failures + " test(s) FAILED");
      System.exit(1);
    } else {
      System.out.println("ALL TESTS PASSED");
      System.exit(0);
    }
  }
}

