package org.openqa.selenium.remote.http;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Regression test for the regex metacharacters bug in UrlTemplate.match(String, String).
 * 
 * The bug: match() uses replaceFirst(prefix, "") where replaceFirst treats the first
 * argument as a regex pattern. If the prefix contains regex special characters
 * (like '.', '[', '(', etc.), it will either throw PatternSyntaxException or produce
 * incorrect matching behavior.
 * 
 * The correct behavior: prefix should be treated as a literal string.
 */
class UrlTemplateRegexPrefixBugTest {

  @Test
  void shouldMatchWithPrefixContainingDot() {
    // '.' is a regex metacharacter matching any character; prefix should be literal.
    UrlTemplate.Match match = new UrlTemplate("/session/{id}/se/vnc")
        .match("/wd/hub/session.1234/se/vnc", "/wd/hub");

    assertNotNull(match, "match should not be null when prefix contains '.'");
    assertEquals("session.1234", match.getParameters().get("id"));
  }

  @Test
  void shouldNotThrowWhenPrefixContainsUnmatchedBracket() {
    // '[' is an invalid regex pattern when unmatched; should not throw.
    UrlTemplate.Match match = new UrlTemplate("/session/{id}")
        .match("/wd[hub/session.1234", "/wd[hub/");

    assertNotNull(match, "match should not be null when prefix contains '['");
    assertEquals("session.1234", match.getParameters().get("id"));
  }

  @Test
  void shouldNotThrowWhenPrefixContainsUnmatchedParen() {
    // '(' is an invalid regex pattern when unmatched; should not throw.
    UrlTemplate.Match match = new UrlTemplate("/session/{id}")
        .match("/wd(hub/session.1234", "/wd(hub/");

    assertNotNull(match, "match should not be null when prefix contains '('");
    assertEquals("session.1234", match.getParameters().get("id"));
  }

  @Test
  void shouldMatchWithPrefixContainingQuestionMark() {
    // '?' is a regex metacharacter; prefix should be literal.
    UrlTemplate.Match match = new UrlTemplate("/session/{id}")
        .match("/wd?hub/session.1234", "/wd?hub/");

    assertNotNull(match, "match should not be null when prefix contains '?'");
    assertEquals("session.1234", match.getParameters().get("id"));
  }

  @Test
  void shouldMatchWithPrefixContainingPlus() {
    // '+' is a regex metacharacter; prefix should be literal.
    UrlTemplate.Match match = new UrlTemplate("/session/{id}")
        .match("/wd+hub/session.1234", "/wd+hub/");

    assertNotNull(match, "match should not be null when prefix contains '+'");
    assertEquals("session.1234", match.getParameters().get("id"));
  }

  @Test
  void shouldMatchWithPrefixContainingAsterisk() {
    // '*' is a regex metacharacter; prefix should be literal.
    UrlTemplate.Match match = new UrlTemplate("/session/{id}")
        .match("/wd*hub/session.1234", "/wd*hub/");

    assertNotNull(match, "match should not be null when prefix contains '*'");
    assertEquals("session.1234", match.getParameters().get("id"));
  }
}

