package org.openqa.selenium.io;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.util.Random;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

@Tag("UnitTests")
class FileHandlerTest {

  /** Standalone entry point for regression testing without JUnit launcher. */
  public static void main(String[] args) {
    int failures = 0;
    FileHandlerTest t = new FileHandlerTest();

    System.out.println("Running: createDirShouldCreateTargetDirectoryAfterParentFix");
    try {
      t.createDirShouldCreateTargetDirectoryAfterParentFix();
      System.out.println("  PASS");
    } catch (AssertionError e) {
      System.err.println("  FAIL: " + e.getMessage());
      failures++;
    } catch (Throwable e) {
      System.err.println("  FAIL: " + e.getClass().getSimpleName() + ": " + e.getMessage());
      failures++;
    }

    System.out.println("Running: createDirShouldNotNpeWhenParentFileIsNull");
    try {
      t.createDirShouldNotNpeWhenParentFileIsNull();
      System.out.println("  PASS");
    } catch (AssertionError e) {
      System.err.println("  FAIL: " + e.getMessage());
      failures++;
    } catch (Throwable e) {
      System.err.println("  FAIL: " + e.getClass().getSimpleName() + ": " + e.getMessage());
      failures++;
    }

    if (failures > 0) {
      System.err.println(failures + " test(s) FAILED");
      System.exit(1);
    } else {
      System.out.println("All tests PASSED");
      System.exit(0);
    }
  }

  @Test
  void testFileCopy() throws IOException {
    File newFile = File.createTempFile("testFileCopy", "dst");
    File tmpFile = writeTestFile(File.createTempFile("FileUtilTest", "src"));
    assertThat(newFile.length()).isZero();
    assertThat(tmpFile.length()).isPositive();

    try {
      // Copy it.
      FileHandler.copy(tmpFile, newFile);

      assertThat(newFile.length()).isEqualTo(tmpFile.length());
    } finally {
      tmpFile.delete();
      newFile.delete();
    }
  }

  @Test
  void createDirShouldNotNpeWhenParentFileIsNull() throws IOException {
    // Bug: When dir.getParentFile() returns null (e.g. root dir), recursive call
    // passes null to createDir(), causing NullPointerException on null.exists().
    // We simulate this by using a File whose getParentFile() returns null.
    // On Unix, "/" has getParentFile() == null but exists(), so we test the
    // edge case through mocking - or we just check that createDir on root
    // doesn't throw NPE.
    File root = new File(System.getProperty("user.dir").replaceFirst("[^/]+(/.*)?$", ""));
    // Verify this actually has null parent
    if (root.getParentFile() == null) {
      // This should not throw NPE even if root exists or doesn't
      FileHandler.createDir(root);
    }
  }

  @Test
  void createDirShouldCreateTargetDirectoryAfterParentFix() throws IOException {
    // Bug: createDir() returns result of parent creation but never retries
    // mkdirs() on the original directory after parent is fixed.
    // We trigger the bug by using a regular FILE as the "parent" so mkdirs() fails,
    // but the file exists and is writable, so the method returns true without
    // creating the actual target directory.
    File parentAsFile = File.createTempFile("createDirParent", ".file");
    try {
      File child = new File(parentAsFile, "child");
      // child.mkdirs() will fail because parentAsFile is a regular file, not a directory.
      // After recursing, createDir(parentAsFile) returns true because the file exists and is writable.
      // But the child directory is never actually created.
      boolean result = FileHandler.createDir(child);

      // Correct behavior: either returns false (can't create in a file) or creates the directory.
      // The bug: returns true without creating child.
      assertThat(result).isFalse();
    } finally {
      parentAsFile.delete();
    }
  }

  private void deleteRecursive(File file) {
    if (file.isDirectory()) {
      File[] children = file.listFiles();
      if (children != null) {
        for (File child : children) {
          child.setWritable(true);
          deleteRecursive(child);
        }
      }
    }
    file.delete();
  }

  private File writeTestFile(File file) throws IOException {
    byte[] byteArray = new byte[16384];
    new Random().nextBytes(byteArray);
    OutputStream out = new FileOutputStream(file);
    out.write(byteArray);
    out.close();
    file.deleteOnExit();
    return file;
  }
}

